def amministratori(apps, schema_editor):
    """Ogni canale esistente ha il suo creatore (o il primo iscritto) come amministratore."""
    Canale = apps.get_model("discuss", "Canale")
    Iscrizione = apps.get_model("discuss", "Iscrizione")
    for canale in Canale.objects.exclude(tipo="diretto"):
        iscritti = Iscrizione.objects.filter(canale=canale).order_by("entrato", "pk")
        scelta = iscritti.filter(utente_id=canale.creato_da_id).first() or iscritti.first()
        if scelta is not None:
            Iscrizione.objects.filter(pk=scelta.pk).update(ruolo="amministratore")


